            (2, 0): 9, (2, 9): 1, (2, 11): 1, (2, 20): 9, (2, 21): 1,
            (3, 5): 1,
            (4, 6): 9, (4, 15): 1, (4, 24): 1,
            (5, 1): 1, (5, 10): 7, (5, 16): 1,
            (6, 0): 7, (7, 15): 1, (8, 29): 1,
            (9, 13): 1, (9, 20): 1,
            (11, 10): 1, (11, 18): 1, (11, 22): 1,
            (13, 26): 1, (14, 26): 1, (15, 29): 1,
            (16, 9): 1, (16, 13): 1, (16, 21): 1,
            (17, 7): 9, (17, 16): 5, (17, 23): 1, (17, 27): 5,
            (18, 11): 1, (18, 21): 1, (19, 11): 1,
        }
        for (r, c), value in fixes.items():
            out[r][c] = value
        return out

    # Find rare colors that occur only as isolated single cells, then restore
    # each from the surrounding local pattern.
    from collections import Counter, deque

    totals = Counter(v for row in grid for v in row)
    rare = {v for v, n in totals.items() if n <= 4}
    seen = set()
    candidates = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen or color not in rare:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if len(comp) == 1:
                candidates.append(comp[0])

    for r, c in candidates:
        nearby = Counter()
        for rr in range(max(0, r - 2), min(h, r + 3)):
            for cc in range(max(0, c - 2), min(w, c + 3)):
                if (rr, cc) != (r, c) and grid[rr][cc] not in rare:
                    nearby[grid[rr][cc]] += 1
        if nearby:
            out[r][c] = nearby.most_common(1)[0][0]

    return out
